import { getPercent } from '../../';

describe('math', () => {
  it('getPercent returns correct value', () => {
    expect(getPercent()).toEqual('0%');
    expect(getPercent(0, 100)).toEqual('0%');
    expect(getPercent(25, 100)).toEqual('25%');
    expect(getPercent(25, 100, 2, true)).toEqual('25.00%');
    expect(getPercent(25, 100, 2, true, true)).toEqual(25.0);
    expect(getPercent(25, 100, 2, false, true)).toEqual(25);
    expect(getPercent(83.12345, 100, 2)).toEqual('83.12%');
    expect(getPercent(100, 100)).toEqual('100%');
    expect(getPercent(100, 200)).toEqual('50%');
    expect(getPercent(0, 0, 2)).toEqual('-.--');
    expect(getPercent(0, 0, 5)).toEqual('-.-----');
    expect(getPercent(0, 0)).toEqual('--');
    expect(getPercent(0, 0, 0, false, true)).toEqual(0);
    expect(getPercent(10)).toEqual('10%');
  });
});
